-- =========================================================
-- RÉFÉRENTIEL PROFESSIONNEL PITIKORANA / FALIMANJAKA
-- 49 domaines, 392 activités et leurs traductions FR/MG.
-- UUID stables : ce seed est idempotent et peut être rejoué.
-- N'alimente volontairement jamais personne_activite.
-- =========================================================

BEGIN;

-- Arrêter avant toute insertion si les deux langues de référence manquent.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM langue WHERE code = 'fr') THEN
    RAISE EXCEPTION 'Langue requise absente : fr';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM langue WHERE code = 'mg') THEN
    RAISE EXCEPTION 'Langue requise absente : mg';
  END IF;
END
$$;

