  FROM langue
  WHERE code IN ('fr', 'mg')
), insertion_domaines AS (
  INSERT INTO domaine_activite (id)
  SELECT id FROM domaines
  ON CONFLICT (id) DO NOTHING
)
INSERT INTO domaine_activite_traduction (id_domaine_activite, id_langue, libelle)
SELECT d.id, l.id,
  CASE l.code WHEN 'fr' THEN d.libelle_fr ELSE d.libelle_mg END
FROM domaines d
CROSS JOIN langues l
ON CONFLICT (id_domaine_activite, id_langue)
DO UPDATE SET libelle = EXCLUDED.libelle;

