), langues AS (
  SELECT id, code
  FROM langue
  WHERE code IN ('fr', 'mg')
), insertion_activites AS (
  INSERT INTO activite (id, id_domaine_activite)
  SELECT id, id_domaine_activite FROM activites
  ON CONFLICT (id) DO UPDATE
  SET id_domaine_activite = EXCLUDED.id_domaine_activite
)
INSERT INTO activite_traduction (id_activite, id_langue, libelle)
SELECT a.id, l.id,
  CASE l.code WHEN 'fr' THEN a.libelle_fr ELSE a.libelle_mg END
FROM activites a
CROSS JOIN langues l
ON CONFLICT (id_activite, id_langue)
DO UPDATE SET libelle = EXCLUDED.libelle;

