), langues AS (
  SELECT id, code
  FROM langue
  WHERE code IN ('fr', 'mg')
), insertion_activites_complementaires AS (
  INSERT INTO activite (id, id_domaine_activite)
  SELECT id, id_domaine_activite FROM activites_complementaires
  ON CONFLICT (id) DO UPDATE
  SET id_domaine_activite = EXCLUDED.id_domaine_activite
)
INSERT INTO activite_traduction (id_activite, id_langue, libelle)
SELECT a.id, l.id,
  CASE l.code WHEN 'fr' THEN a.libelle_fr ELSE a.libelle_mg END
FROM activites_complementaires a
CROSS JOIN langues l
ON CONFLICT (id_activite, id_langue)
DO UPDATE SET libelle = EXCLUDED.libelle;
COMMIT;

-- =========================================================
-- CONTRÔLES POST-SEED (lecture seule)
-- =========================================================

-- Nombre total de domaines et d'activités du référentiel.
SELECT count(*) AS nombre_domaines FROM domaine_activite;
SELECT count(*) AS nombre_activites FROM activite;

-- Nombre de traductions FR/MG disponibles.
SELECT l.code, count(*) AS traductions_domaines
FROM domaine_activite_traduction dt
JOIN langue l ON l.id = dt.id_langue
WHERE l.code IN ('fr', 'mg')
GROUP BY l.code
ORDER BY l.code;

SELECT l.code, count(*) AS traductions_activites
FROM activite_traduction at
JOIN langue l ON l.id = at.id_langue
WHERE l.code IN ('fr', 'mg')
GROUP BY l.code
ORDER BY l.code;

-- Anomalies à attendre à zéro pour les données introduites par ce seed.
SELECT count(*) AS activites_sans_domaine
FROM activite
WHERE id_domaine_activite IS NULL;

SELECT d.id AS id_domaine, l.code AS langue_sans_traduction
FROM domaine_activite d
CROSS JOIN (SELECT id, code FROM langue WHERE code IN ('fr', 'mg')) l
LEFT JOIN domaine_activite_traduction dt
  ON dt.id_domaine_activite = d.id AND dt.id_langue = l.id
WHERE dt.id IS NULL
ORDER BY d.id, l.code;

SELECT a.id AS id_activite, l.code AS langue_sans_traduction
FROM activite a
CROSS JOIN (SELECT id, code FROM langue WHERE code IN ('fr', 'mg')) l
LEFT JOIN activite_traduction at
  ON at.id_activite = a.id AND at.id_langue = l.id
WHERE at.id IS NULL
ORDER BY a.id, l.code;
-- UUID du seed dupliqués : ce résultat doit être vide.
WITH uuid_seed AS (
  SELECT id FROM domaine_activite WHERE id::text LIKE '13000000-0000-4000-8000-%'
  UNION ALL
  SELECT id FROM activite WHERE id::text LIKE '13000000-0001-4000-8000-%'
  UNION ALL
  SELECT id FROM activite WHERE id::text LIKE '13000000-0002-4000-8000-%'
)
SELECT id, count(*) AS occurrences
FROM uuid_seed
GROUP BY id
HAVING count(*) > 1;

-- Libellés français dupliqués dans un même domaine : résultat attendu vide.
SELECT a.id_domaine_activite, at.libelle, count(*) AS occurrences
FROM activite a
JOIN activite_traduction at ON at.id_activite = a.id
JOIN langue l ON l.id = at.id_langue AND l.code = 'fr'
GROUP BY a.id_domaine_activite, at.libelle
HAVING count(*) > 1
ORDER BY a.id_domaine_activite, at.libelle;

-- Activités sans traduction française puis malagasy : résultats attendus vides.
SELECT a.id AS activite_sans_fr
FROM activite a
LEFT JOIN activite_traduction at ON at.id_activite = a.id
LEFT JOIN langue l ON l.id = at.id_langue AND l.code = 'fr'
GROUP BY a.id
HAVING count(l.id) = 0
ORDER BY a.id;

SELECT a.id AS activite_sans_mg
FROM activite a
LEFT JOIN activite_traduction at ON at.id_activite = a.id
LEFT JOIN langue l ON l.id = at.id_langue AND l.code = 'mg'
GROUP BY a.id
HAVING count(l.id) = 0
ORDER BY a.id;

-- Répartition réelle des activités par domaine.
SELECT dt.libelle AS domaine, count(a.id) AS nombre_activites
FROM domaine_activite d
JOIN domaine_activite_traduction dt ON dt.id_domaine_activite = d.id
JOIN langue l ON l.id = dt.id_langue AND l.code = 'fr'
LEFT JOIN activite a ON a.id_domaine_activite = d.id
GROUP BY d.id, dt.libelle
ORDER BY nombre_activites DESC, dt.libelle;